{"actions":[{"type":"raw_bash","command":"set -euo pipefail
cd /app
if command -v qemu-system-i386 >/dev/null 2>&1; then QEMU_BIN=qemu-system-i386; elif command -v qemu-system-x86_64 >/dev/null 2>&1; then QEMU_BIN=qemu-system-x86_64; else echo 'NO_QEMU_BIN'; exit 1; fi
cat > /app/win311-qemu.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
QEMU_BIN=${QEMU_BIN:-qemu-system-i386}
IMG=/app/isos/win311.img
exec "$QEMU_BIN" \
  -m 32 \
  -cpu 486 \
  -machine pc \
  -drive file="$IMG",if=ide,format=raw,snapshot=on \
  -vnc 127.0.0.1:1 \
  -monitor unix:/tmp/win311-monitor.sock,server,nowait \
  -serial mon:stdio \
  -rtc base=localtime \
  -net none
EOF
chmod +x /app/win311-qemu.sh
mkdir -p /app/www
cat > /app/www/index.html <<'EOF'
<!doctype html><html><body><h1>Windows 3.11 VM Remote Access</h1><p>QEMU VNC: 127.0.0.1:5901</p></body></html>
EOF
if command -v nginx >/dev/null 2>&1; then
  cat > /tmp/nginx-win311.conf <<'EOF'
worker_processes  1;
events { worker_connections  1024; }
http {
  include       mime.types;
  default_type  application/octet-stream;
  sendfile        on;
  keepalive_timeout  65;
  server {
    listen 80;
    server_name _;
    root /app/www;
    index index.html;
  }
}
EOF
  nginx -c /tmp/nginx-win311.conf
fi
nohup env QEMU_BIN="$QEMU_BIN" /app/win311-qemu.sh >/tmp/win311-qemu.log 2>&1 &
sleep 2
ps -ef | grep -E '[q]emu-system-(i386|x86_64).*win311.img' || true
ss -ltnp | grep ':5901\b' || true
ss -ltnp | grep ':80\b' || true
printf 'monitor socket: '; test -S /tmp/win311-monitor.sock && echo yes || echo no
